package audit

import (
	"encoding/hex"
	"fmt"
	"testing"
	"time"

	"github.com/ctlplne/probectl/internal/crypto"
)

// Captured from the unmodified v0.6.5 binary during the upgrade rehearsal.
// This fixed oracle must never be regenerated by the current hash function.
func historicalProviderEvent() Event {
	return Event{Seq: 1, Actor: "system", Action: "license.loaded", Target: "license",
		Data:      map[string]any{"tier": "core", "state": "community", "customer": "", "license_id": "", "trust_anchors": float64(2)},
		Hash:      "cbe796d7aef3a5606829d60d319dd3c961b3ce2025f18949af2936dc016e3190",
		CreatedAt: time.Date(2026, 10, 26, 21, 46, 25, 729057000, time.UTC)}
}

func TestV065ProviderEventSurvivesUpgrade(t *testing.T) {
	old := historicalProviderEvent()
	if err := validateProviderSource([]Event{old}, 0, ""); err != nil {
		t.Fatalf("untouched v0.6.5 event refused: %v", err)
	}
	canonical, err := canonicalAuditData(map[string]any{"step": "after-upgrade"})
	if err != nil {
		t.Fatal(err)
	}
	next := Event{Seq: 2, Actor: "system", Action: "upgrade.verified", Target: "qa", Data: map[string]any{"step": "after-upgrade"}, PrevHash: old.Hash, CreatedAt: old.CreatedAt.Add(time.Minute), canonicalData: canonical}
	next.Hash = chainEventHash(providerStream, next.Seq, next.Actor, next.Action, next.Target, next.CreatedAt.UnixMicro(), canonical, next.PrevHash)
	if err := validateProviderSource([]Event{old, next}, 0, ""); err != nil {
		t.Fatalf("mixed-vintage chain refused: %v", err)
	}
	for _, dropCanonical := range []bool{false, true} {
		bad := next
		bad.CreatedAt = bad.CreatedAt.Add(time.Hour)
		if dropCanonical {
			bad.canonicalData = nil
		}
		if err := validateProviderSource([]Event{bad}, 1, old.Hash); err == nil {
			t.Fatalf("new timestamp tampering accepted (canonical removed=%v)", dropCanonical)
		}
	}
}

func TestV065ProviderEventTamperingStillRefused(t *testing.T) {
	for _, change := range []struct {
		name   string
		mutate func(*Event)
	}{
		{"actor", func(e *Event) { e.Actor = "other" }},
		{"action", func(e *Event) { e.Action = "other" }},
		{"target", func(e *Event) { e.Target = "other" }},
		{"payload", func(e *Event) { e.Data["tier"] = "msp" }},
		{"previous hash", func(e *Event) { e.PrevHash = "other" }},
		{"canonical marker", func(e *Event) {
			e.canonicalData = []byte(`{"customer":"","license_id":"","state":"community","tier":"core","trust_anchors":2}`)
		}},
	} {
		t.Run(change.name, func(t *testing.T) {
			e := historicalProviderEvent()
			change.mutate(&e)
			if err := validateProviderSource([]Event{e}, 0, ""); err == nil {
				t.Fatal("tampered historical event accepted")
			}
		})
	}
}

func TestV065HashDoesNotAdmitAmbiguousHeadersOrForeignStreams(t *testing.T) {
	e := historicalProviderEvent()
	got, err := eventHash("different-tenant", e)
	if err != nil {
		t.Fatal(err)
	}
	if got == e.Hash {
		t.Fatal("historical event moved to another stream")
	}
	for _, actor := range []string{"system" + string('\n') + "actor", "system" + string('\\') + "actor"} {
		e = historicalProviderEvent()
		e.Actor = actor
		canonical, err := canonicalAuditData(e.Data)
		if err != nil {
			t.Fatal(err)
		}
		header := fmt.Sprintf("provider\n1\n%s\nlicense.loaded\nlicense\n\n", actor)
		e.Hash = hex.EncodeToString(crypto.Hash(append([]byte(header), canonical...)))
		if err := validateProviderSource([]Event{e}, 0, ""); err == nil {
			t.Fatal("ambiguous legacy header accepted")
		}
	}
}
